  insert into public.agenda_items
    (id, assembly_id, item_number, title, category, proposal_reason, status, decided_on, display_order)
  values
    ('f9158131-4619-4752-a3a5-a6963ef521eb', v_assembly_id, '認定第1号', '令和6年度広川町一般会計歳入歳出決算の認定について', '決算認定', '令和6年度広川町一般会計歳入歳出決算の認定について。歳入総額9,771,762,003円、歳出総額9,201,675,994円、実質収支478,038,009円の黒字。11名で構成する一般会計等決算特別委員会に付託の上審査され、賛成多数で認定すべきものと決定。本会議の起立採決でも起立多数で認定。江藤美代子議員は不用額(358,220千円)・多額の繰越金、税・料金の滞納増加、同和対策事業への反対を理由に反対討論を行い、丸山幸弘議員が賛成討論を行った。', '可決', '2025-09-19', 1),
    ('e94ca816-f7c3-443c-a157-c8333adc80f2', v_assembly_id, '認定第2号', '令和6年度広川町国民健康保険特別会計歳入歳出決算の認定について', '決算認定', '令和6年度広川町国民健康保険特別会計歳入歳出決算の認定について。歳入総額2,220,779,364円、歳出総額2,198,259,434円、実質収支22,260,930円。決算特別委員会で賛成多数、本会議の起立採決でも起立多数で認定。江藤美代子議員は国保運営の県移行に伴う保険料負担増を理由に反対討論、丸山幸弘議員が賛成討論を行った。', '可決', '2025-09-19', 2),
    ('2f6c193a-eacb-4e50-be98-405a9e261011', v_assembly_id, '認定第3号', '令和6年度広川町後期高齢者医療特別会計歳入歳出決算の認定について', '決算認定', '令和6年度広川町後期高齢者医療特別会計歳入歳出決算の認定について。歳入総額355,992,393円、歳出総額345,030,689円、実質収支10,961,704円。決算特別委員会で全会一致、本会議でも異議なく認定。', '可決', '2025-09-19', 3),
    ('b1b148d5-3625-4b84-8152-2ef5081887c7', v_assembly_id, '認定第4号', '令和6年度広川防災ダム管理特別会計歳入歳出決算の認定について', '決算認定', '令和6年度広川防災ダム管理特別会計歳入歳出決算の認定について。歳入総額28,274,646円、歳出総額25,916,884円、実質収支2,357,762円。決算特別委員会で全会一致、本会議でも異議なく認定。', '可決', '2025-09-19', 4),
    ('e6f4ea0c-d643-46ee-adee-b3dde2fa8931', v_assembly_id, '認定第5号', '令和6年度広川町水道事業会計決算の認定について', '決算認定', '令和6年度広川町水道事業会計決算の認定について。収益的収入396,749,324円・支出307,259,026円、当年度純利益87,524,090円。決算特別委員会で全会一致、本会議でも異議なく認定。', '可決', '2025-09-19', 5),
    ('58437562-788f-405e-98da-2b6eca2bb0a3', v_assembly_id, '認定第6号', '令和6年度広川町下水道事業会計決算の認定について', '決算認定', '令和6年度広川町下水道事業会計決算の認定について。収益的収入404,427,708円・支出372,147,167円、当年度純利益25,778,302円。決算特別委員会で全会一致、本会議でも異議なく認定。', '可決', '2025-09-19', 6),
    ('cf957a64-4fa9-416b-946b-b6b3c2623550', v_assembly_id, '報告第4号', '令和6年度決算に基づく健全化判断比率等の報告について', '報告', '地方公共団体の財政の健全化に関する法律第3条・第22条の規定に基づく報告。実質公債費比率8.3%(前年度比0.1pt改善)、将来負担比率20.1%(前年度比4pt改善)等、いずれも早期健全化基準を下回る。水道・下水道事業とも資金剰余のため資金不足比率は算定なし。議決を要さない報告事項。', '可決', '2025-09-11', 7),
    ('d63f881b-520f-49cc-918e-8089ad5c762a', v_assembly_id, '同意第2号', '広川町固定資産評価審査委員会委員の選任に対する同意について', '人事', '広川町固定資産評価審査委員会委員として田中由美子氏を選任したいので、地方税法第423条第3項の規定により議会の同意を求めるもの。委員野中久子氏の任期満了(令和7年9月30日)に伴う後任選任。', '可決', '2025-09-11', 8),
    ('b9174689-5caf-45b3-9b24-beff22a70a5c', v_assembly_id, '諮問第1号', '人権擁護委員候補者の推薦について', '人事', '人権擁護委員候補者として安達幸子氏を推薦したいので、人権擁護委員法第6条第3項の規定により議会の意見を求めるもの。委員山下整子氏の任期満了(令和7年12月31日)に伴う後任候補者の推薦。', '可決', '2025-09-11', 9),
    ('d583179a-2141-4829-90b7-e29cbd876629', v_assembly_id, '議案第43号', '広川町役場課設置条例の一部改正について', '条例の改正', '令和7年10月1日に実施する組織機構改革(都市計画課の新設等)のため一部改正するもの。現行8課体制から都市計画課を新設し9課体制とする。', '可決', '2025-09-11', 10),
    ('f5a21a83-9970-4f4d-9e20-2a2f91b0d6de', v_assembly_id, '議案第44号', '広川町職員定数条例の一部改正について', '条例の改正', '組織機構改革に伴う農業委員会事務部局の職員定数見直しのため一部改正するもの。職員定数を155人(うち兼務25人)から158人(うち兼務28人)に改める(定数上限130人自体は変更なし)。', '可決', '2025-09-11', 11),
    ('d9e7aade-1c1f-4881-9a4d-bc766e0fb532', v_assembly_id, '議案第45号', '広川町議会議員及び広川町長の選挙における選挙運動の公費負担に関する条例の一部改正について', '条例の改正', '公職選挙法施行令の一部改正により衆参両院選挙の選挙運動公費負担限度額が引き上げられたことに伴い、選挙運動用ビラ(7円73銭→8円38銭)及びポスター(541円31銭→586円88銭)の公費負担単価の限度額を引き上げるもの。', '可決', '2025-09-11', 12),
    ('a688c108-3e76-4986-adc7-d0b6b9272d1b', v_assembly_id, '議案第46号', '広川町職員の勤務時間及び休暇等に関する条例の一部改正について', '条例の改正', '育児休業、介護休業等育児又は家族介護を行う労働者の福祉に関する法律の一部改正に伴い、子を養育する職員への両立支援制度の情報提供・意向確認を義務化するため一部改正するもの。', '可決', '2025-09-11', 13),
    ('266dcce4-0ff7-42d9-af7b-0643abf1798b', v_assembly_id, '議案第47号', '広川町職員の育児休業等に関する条例の一部改正について', '条例の改正', '地方公務員の育児休業等に関する法律の一部改正による部分休業制度の拡充(1時間単位で柔軟に取得できる新たな部分休業制度の創設、年間上限77時間30分)のため一部改正するもの。', '可決', '2025-09-11', 14),
    ('9cc8d0e7-defb-4f69-aa1e-9eccfec72bfd', v_assembly_id, '議案第48号', '広川町会計年度任用職員の給与及び費用弁償に関する条例の一部改正について', '条例の改正', 'パートタイム会計年度任用職員の勤務1時間当たりの報酬額の計算方法・端数処理(10円未満切り上げ)を明確化するため一部改正するもの。', '可決', '2025-09-11', 15),
    ('276dff8c-c7e3-4216-8536-bb966233d7dd', v_assembly_id, '議案第49号', '広川町水道布設工事監督者の配置及び資格並びに水道技術管理者の資格に関する条例の一部改正について', '条例の改正', '建設業法施行令の一部改正に伴う条ずれ整理のため一部改正するもの。', '可決', '2025-09-11', 16),
    ('79f1b519-7cdc-485b-89fb-1a210861470f', v_assembly_id, '議案第50号', '公用車購入に係る契約の締結について', '契約の締結', '公用車購入(契約額6,518,660円、契約の相手方:福岡トヨタ自動車株式会社久留米南店)について、一般競争入札により定めた契約者と契約を締結するもの。7人乗りハイブリッド車で、町長・議会の移動や職員研修、来客対応等に使用予定。', '可決', '2025-09-11', 17),
    ('7f392668-b5ee-44b1-83ec-653d192191a9', v_assembly_id, '議案第51号', '広川町移住定住促進センター兼滞在交流施設及び広川町ものづくり研究所の指定管理者の指定について', '指定管理者の指定', '広川町移住定住促進センター兼滞在交流施設(Orige)及び広川町ものづくり研究所(Hodoku)の指定管理者として有限会社坂田織物(代表取締役 坂田和生)を指定するもの(指定期間:令和7年10月1日〜令和10年3月31日)。ネイティブテキスタイル産地プロジェクトの活動拠点として活用するため、プロジェクト協議会参加事業者からの特命随意契約により選定。', '可決', '2025-09-11', 18),
    ('2617c73e-5577-4cce-8d7a-99f03a55b7f2', v_assembly_id, '議案第52号', '令和7年度広川町一般会計補正予算（第3号）について', '補正予算', '歳入歳出予算の総額に歳入歳出それぞれ92,621千円を追加し、予算総額を9,831,236千円とするもの。普通交付税の交付決定(208,330千円増)、企業版ふるさと納税寄付金の計上、地域防災拠点施設(消防団第5分団)建築工事費58,190千円の繰越明許費等が主な内容。', '可決', '2025-09-11', 19),
    ('1e5204ec-0d23-439e-82c1-cf4e9481dc67', v_assembly_id, '議案第53号', '令和7年度広川町国民健康保険特別会計補正予算（第2号）について', '補正予算', '既定の予算総額に14,827千円を追加し、予算総額を2,293,959千円とするもの。国民健康保険財政調整基金積立金17,538千円の増額等が内容。', '可決', '2025-09-11', 20),
    ('036ddae1-dce6-401b-896e-daa4330a4560', v_assembly_id, '議案第54号', '令和7年度広川町後期高齢者医療特別会計補正予算（第2号）について', '補正予算', '既定の予算総額に6,961千円を追加し、予算総額を381,722千円とするもの。後期高齢者医療広域連合納付金の増額が内容。', '可決', '2025-09-11', 21),
    ('ed3c3bcc-fa80-45fa-bbf1-23292cc32393', v_assembly_id, '議案第55号', '令和7年度広川防災ダム管理特別会計補正予算（第1号）について', '補正予算', '予算総額は補正せず、令和6年度決算確定に伴う繰越金2,157千円の増額及び一般会計繰入金の同額減額を行うもの。', '可決', '2025-09-11', 22),
    ('48a4db97-b456-4ca7-aa3c-c1e5624ac00a', v_assembly_id, '議案第56号', '令和7年度広川町水道事業会計補正予算（第1号）について', '補正予算', '収益的収入100千円・支出320千円増額、資本的収入180千円増額・支出2,080千円減額し、予算総額407,707千円とするもの。給与改定等に伴う人件費の補正が主な内容。', '可決', '2025-09-11', 23),
    ('c47ee386-26c5-4cd3-ab71-63721214acd1', v_assembly_id, '議案第57号', '令和7年度広川町下水道事業会計補正予算（第1号）について', '補正予算', '収益的収入132千円・支出122千円増額、資本的支出10千円増額し、予算総額613,280千円とするもの。人件費の補正が内容。', '可決', '2025-09-11', 24),
    ('864dd689-be1c-45fa-bc5b-2dd42a8caeda', v_assembly_id, '議案第58号', '令和6年度広川町水道事業会計決算剰余金の処分について', '決算剰余金の処分', '地方公営企業法第32条第2項の規定に基づき、令和6年度事業年度末の決算剰余金を処分するもの。当年度未処分利益剰余金88,029,585円のうち88,000千円を建設改良積立金として処分し、残額29,585円を翌年度繰越利益剰余金とする。', '可決', '2025-09-19', 25),
    ('081337b4-aa63-450b-b05c-6fe4cc4e95c2', v_assembly_id, '発委第1号', '広川町議会委員会条例の一部改正について', '条例の改正', '広川町役場課設置条例の改正(都市計画課新設)に伴い、広川町議会委員会条例第2条(総務産業常任委員会の所管)に都市計画課を追加するため一部改正するもの。議会運営委員会提出(提出者:池尻浩一委員長)。', '可決', '2025-09-19', 26);
