  insert into public.question_topics
    (id, general_question_id, topic_title, raw_excerpt, department, display_order)
  values
    ('06d55c82-3238-44db-977d-dd4f9d7eb57a', 'd9e89e25-9926-49bc-9966-a9a755ce29c5', 'クーリングシェルター指定後の利用状況と今後の課題', '6月末の指定以降、庁舎・いこっと・はなやぎの里・産業展示会館・古墳資料館(7/19〜8/20で12人利用)等を指定、民間ではホームホスピスあいのさとが協力。地区公民館(久泉・緑ケ丘・増永・川瀬等)も夏休み中クーリングシェルターを兼ねて開放。今年度の熱中症搬送は24件(高齢者は前年27件から16件に減少)。今後の課題として利用実績データの継続把握、公民館開放時の人手不足、周知方法の分かりやすさ等が挙げられた。', '環境課', 1),
    ('708c2f9a-a32e-4830-9210-aee80108e454', 'd9e89e25-9926-49bc-9966-a9a755ce29c5', '町の広報の現状と課題', '広報ヒロカワは紙版・デジタル版を併用、公式LINE登録者数は5,830名。企画課長は配信頻度・デジタルデバイド対策・世代別ニーズへの対応が課題と説明。下田議員は紙・デジタルの選択制によるコストカットやSNSの再活用を提案したが、フェイスブックは平成26年〜令和3年運用後、フォロワー数減少により閉鎖済みとの回答があった。', '企画課', 2),
    ('3788eeeb-347c-4ee0-b84f-bf317d79d7f3', '140ec09d-ee46-49e3-9e75-ba32b95d31ec', 'LGBT理解増進法と義務教育における対応', 'LGBT理解増進法の国の基本計画は未策定、学習指導要領にも未反映であることを確認した上で、広川町の人権教育は法務省が示す人権課題の枠組みで行われており、同法に基づくものではないと子ども課長が答弁。竹下議員は同法の成立過程や条文(第6条・第12条)の内容を詳細に説明し、地域の実情把握や教職員研修の必要性を議論した。', '生涯学習課', 1),
    ('e224e4b4-b991-4d68-8c57-e93b8b0b6843', '140ec09d-ee46-49e3-9e75-ba32b95d31ec', '公共施設の指定管理の考え方', '産業展示会館(商工会)・逆瀬ゴットン館(さかせ会)・保健福祉センターはなやぎの里(社会福祉協議会)等の指定管理の選定・評価プロセスを確認。竹下議員はOrige・Kibiruの指定管理者交代(ニュー・ヒロカワ合同会社→坂田織物)の経緯や、成果連動型民間委託契約(PFS)導入の検討状況を質問し、福祉課長は次期契約に向け検討する旨を答弁した。', '産業課', 2),
    ('1121f2c6-4204-4425-b3d8-1cdea8268935', '140ec09d-ee46-49e3-9e75-ba32b95d31ec', '農業(米増産政策の広川町への影響)', '国の減反政策から増産政策への転換について、広川町は施設園芸が主で水田農業での生計は少なく(1軒あたり作付約5反)、農業委員会でも米問題を協議していると産業課長が説明。竹下議員は農地集約・スマート農業・小規模兼業農家の減少等、構造的要因についても議論した。', '産業課', 3),
    ('c2305613-2e78-49dd-83c9-3d8ee3f0a452', '140ec09d-ee46-49e3-9e75-ba32b95d31ec', 'その他(eスポーツ事業の検証、鬼ノ渕行政区の空き家問題)', 'eスポーツ事業の令和8年度以降の事業計画イメージ、財源(企業版ふるさと納税継続の是非)について質問。福祉課長は3課(福祉課・生涯学習課・企画課)で検証を進め予算に反映すると答弁。鬼ノ渕行政区の所有者不在の空き家については、相続財産清算人選任等の手続上の課題があり、環境課はコンタクト実績なしと回答、竹下議員は上広川校区の過疎対策の観点からの検討を要望した。', '福祉課', 4),
    ('bcd0512f-f257-4d00-bcdd-41bbe4ee205e', 'ba1627b3-f20e-4184-a414-24d3943dfb3e', '生活安全・防犯(防犯カメラの設置状況)', '町設置の防犯カメラは36台(令和元年度から設置開始)、これまで捜査への画像提供62件(延べ89台分)。地元要望に基づく設置は令和5年度のみ受付、令和7年度は2台設置予定(1台あたり460〜500千円超、県補助は2分の1・上限200千円)。個人設置への補助制度は現在なく、県の設置基準等を踏まえ町として検討課題としている。', '企画課', 1),
    ('503646f7-0edf-4672-b9a9-031c063df3af', 'ba1627b3-f20e-4184-a414-24d3943dfb3e', 'eスポーツ事業の成果と今後の取組', '令和5年12月開始から令和7年7月末までに体験会・交流会に延べ2,492人参加。認知機能テストで正解率向上等の効果が中間報告で示された。池尻議員は自主的参加者の減少傾向や地域差(温度差)を指摘し、福祉課長は次期(3〜5か年)計画の中で継続支援の在り方を検討すると答弁した。', '福祉課', 2),
    ('d3ea23e2-57d0-4dd0-ba1e-062d2c60c862', '0cc6f171-3fd7-43a7-8468-e110a428cf8f', '広川町の小・中学校の学力の状況', '令和7年度全国学力・学習状況調査で、広川町は小学校国語0.8pt・算数5.0pt、中学校国語・数学ともに3.3pt、全国平均を下回った。「授業がよく分かる」の割合は中学校で国語マイナス14.3pt・数学マイナス6.7ptと特に低い。県立高校進学は推薦53名・特色化選抜5名・一般54名(私立含め一般入試受験者は延べ178名)。梶原議員は非認知能力向上に偏重せず「分かる授業」への改善と、全国調査以外の町独自の学力評価基準の検討を求めたが、子ども課長は独自基準は考えていないと答弁。', '教育委員会事務局子ども課', 1),
    ('bd82cf00-e972-4182-a2a1-28bf7dedc7f6', '0cc6f171-3fd7-43a7-8468-e110a428cf8f', '部活の地域移行', '広川中学校の部活動(運動部13・文化部3、計16部)のうち、令和6年度は卓球部・ブラスバンド部、令和7年度はソフトボール部・剣道部・バスケットボール部の休日活動が地域クラブへ移行済み。令和8年度からは平日(月水金)16時45分以降も対象となる予定。地域クラブ活動指導員の報酬は時給1,600円、指導者確保・保護者の費用負担・理解促進が課題として挙げられた。', '教育委員会事務局子ども課', 2),
    ('392fb007-b4ff-47c4-be90-6352a756d75b', '926a048f-7a02-465b-bf10-8363e2847d1c', '広川町公共施設等総合管理計画', '平成29年策定・令和6年改定の計画について、延べ床面積はほぼ横ばい(4.7万→4.8万平米)だが維持管理費は約4.1倍(172,170千円→709,000千円、集計前提の変更が主因)に増加していることを指摘。公共建築物の更新費用は建替パターンで137億円、長寿命化パターンで153億円と試算。産業展示会館(まち子のおやつ4店舗中1店舗のみ稼働)、Kibiru・Orige・Hodokuの活用状況、一部事務組合施設(八女地区消防組合庁舎建替等)の財政負担、上広川小学校移転に伴う複合施設化について質疑応答が行われた。', '総務課', 1),
    ('bac13697-6558-4248-89e0-f7191d052fce', '455af9e1-9338-4e71-8da7-3dc5372f8ef8', '申請が必要な支援制度(高額療養費・特別障害者手当・家族介護用品給付)', '国民健康保険高額療養費は令和7年2〜4月診療分から領収書提示を原則不要化。令和6年度分では未支給が304月・2,420千円残っている状況。特別障害者手当の受給者は19名。家族介護用品給付事業は非課税17世帯・課税22世帯が受給(令和6年度給付額1,981千円)。江藤議員は制度周知の徹底と申請漏れ対策の強化を求めた。', '住民課', 1),
    ('a7ffe913-a89a-4ec2-8e53-01b2f0580737', '455af9e1-9338-4e71-8da7-3dc5372f8ef8', '子育て支援(こどもまんなかアクションプラン・給食費無償化・就学援助)', 'こどもまんなかアクションプランでは子供医療費無償化年齢引上げ・竜光寺公園リニューアル等を実施。就学援助認定者221名(認定率13.1%)、特別支援教育就学奨励費40名。学校給食費の無償化について、町長は選挙公約であり財源確保でき次第実施したいとしつつ、国の小学校給食無償化の動向を注視し慎重に検討中と答弁。江藤議員は恒久化を待たず段階的な補助からでも実施するよう要望した。', '教育委員会事務局子ども課', 2),
    ('c885fccc-f2c4-445f-8a97-3a68cd26ae29', 'b50ad45f-00fb-4e35-b6e0-13211d8ff13d', '各種事業の進捗状況(ゼロカーボンシティ・水害復興・こどもまんなか・SDGs)と事業資金', '令和4年12月ゼロカーボンシティ宣言後、公共施設5か所への太陽光発電・蓄電池設置(PPA事業)等を実施。令和5年7月豪雨の災害復旧30か所のうち27か所が令和7年8月末までに完了(残る長延逆瀬谷線・松川原橋・高山橋は令和7年度内完了見込み)。県営浸水対策重点地域緊急事業は堰統廃合計画・詳細設計等を実施中。こどもまんなか政策・SDGs啓発事業の進捗も説明された。', '企画課', 1),
    ('a11fbebe-bcc8-4f3e-b3ee-8971284118ee', 'b50ad45f-00fb-4e35-b6e0-13211d8ff13d', 'ふるさと納税の実績と使途', '個人版ふるさと納税は令和6年度236,690,600円(前年度比約154%増、委託事業所の変更や返礼品企画強化が奏功)、企業版は16,454,800円(前年度比約38%減)。個人版は子供医療費助成・有害鳥獣対策・図書購入費等に、企業版は公金収納セルフレジ導入やeスポーツ事業等の地域再生計画掲載事業に充当。藤島議員は奨学金返済支援への活用を提案したが、現時点で該当項目はなく今後の検討課題とされた。', '企画課', 2),
    ('945bf18f-6fff-4e17-8a9e-65166dea3f1a', 'b50ad45f-00fb-4e35-b6e0-13211d8ff13d', '教育事業(学校施設の維持管理)', '広川中学校武道場のエアコン未設置による夏場の暑さ対策について、生涯学習課長は他自治体の事例や機種等の情報収集を進めていると説明。学校施設の維持管理は法定点検・県検査等の結果を踏まえ、緊急性に応じて予算に反映していると回答があった。', '生涯学習課', 3),
    ('c0c048d8-b17f-4fab-88ec-51836a9892cb', 'b50ad45f-00fb-4e35-b6e0-13211d8ff13d', '都市計画について', '昭和50年から町全域が都市計画区域に指定されているが、市街化区域・調整区域の区分や用途地域指定はなし。都市計画課新設(令和7年10月予定)や国道3号バイパス事業等を背景とした都市計画の今後の方向性を質問。議長より、審議前の議案(役場課設置条例)に関わる内容として質問を制限する場面があった。', '建設課', 4);
  insert into public.question_topics
    (id, general_question_id, topic_title, raw_excerpt, department, display_order)
  values
    ('e360a4da-8784-41ea-a4a1-d6288e9765cf', 'b50ad45f-00fb-4e35-b6e0-13211d8ff13d', '区長会からの質問事項への対応', '行政区長懇談会等を通じて区長会から寄せられる質問・要望(道路・河川・環境関係が6〜7割を占める)は、企画課が取りまとめて各担当課に配分し、回答を区長へ返す流れで対応していると説明。藤島議員は現場を知る区長の声をより丁寧に施策へ反映するよう求めた。', '企画課', 5);
