-- purpose: 令和7年第3回(9月)定例会のデータを会議録から新規投入する
-- affected: assemblies, agenda_items, general_questions, question_topics
-- sources:
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/070904.pdf (9/4 開会・一般質問)
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/070911.pdf (9/11 議案審議・決算特別委員会設置)
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/070919.pdf (9/19 決算特別委員会報告・採決・閉会)
-- notes: total_agenda_itemsは開会時の町長挨拶で示された「決算認定6件、報告1件、人事案件2件、
--        条例の改正7件、契約の締結及び指定管理者の指定各1件、補正予算6件、
--        水道事業会計決算剰余金の処分1件の計25件」に基づく。
--        議会運営委員会提出の発委第1号(議会委員会条例の一部改正)はこの25件には含まれないが、
--        20260830150000のr7-4発議第1号と同様の扱いでagenda_itemsに1件追加登録する(合計26件)。
--        認定第1号(一般会計)・認定第2号(国保特会)は9/19の本会議で起立採決の結果、
--        起立多数で可決(認定)。反対討論(江藤美代子議員)・賛成討論(丸山幸弘議員)があったが、
--        丸山幸弘議員は本番council_membersに未登録かつ一般質問者ではないため、
--        今回のマイグレーションでは新規作成しない(必要になった際に別途対応)。
--        agenda_items.statusはCHECK制約(可決・否決・継続審査・撤回・未審議のみ)に対応するため、
--        認定→可決、報告→可決、同意・諮問(人事案件)→可決の変換ルールを適用。
--        本会議での意思決定日(decided_on)は、認定第1〜6号・議案第58号・発委第1号は
--        決算特別委員会報告と最終採決が行われた9/19、その他(報告第4号・同意第2号・諮問第1号・
--        議案第43〜57号)は審議・採決当日の9/11とする。
--        council_membersは全員(下田めぐみ・竹下英治・池尻浩一・梶原一美・山下茂・江藤美代子・
--        藤島玄稔)が既存レコードで解決できるため、新規作成は行わない。

do $$
declare
  v_assembly_id uuid := '78c69403-1e60-4da6-a4e2-63a150f8b099';
begin

  -- 冪等ガード: 既に投入済みなら何もしない
  if exists (
    select 1 from public.assemblies
    where fiscal_year = 2025
      and session_type = '定例会'
      and session_number = 3
  ) then
    raise notice '既に投入済みのためスキップします';
    return;
  end if;


  -- agenda_items

  -- general_questions: council_member_idは氏名で既存レコードを解決する
  select 'd9e89e25-9926-49bc-9966-a9a755ce29c5', v_assembly_id, cm.id, 1, 'クーリングシェルター指定後の利用状況、町の広報の現状と課題について'
  from public.council_members cm where cm.name = '下田めぐみ';

  select '140ec09d-ee46-49e3-9e75-ba32b95d31ec', v_assembly_id, cm.id, 2, 'LGBT理解増進法と義務教育、公共施設の指定管理、農業(米問題)、その他(eスポーツ・空き家問題)について'
  from public.council_members cm where cm.name = '竹下英治';

  select 'ba1627b3-f20e-4184-a414-24d3943dfb3e', v_assembly_id, cm.id, 3, '町の生活安全・防犯(防犯カメラ)、eスポーツについて'
  from public.council_members cm where cm.name = '池尻浩一';

  select '0cc6f171-3fd7-43a7-8468-e110a428cf8f', v_assembly_id, cm.id, 4, '広川町の小・中学校の学力の状況、部活の地域移行について'
  from public.council_members cm where cm.name = '梶原一美';

  select '926a048f-7a02-465b-bf10-8363e2847d1c', v_assembly_id, cm.id, 5, '広川町公共施設等総合管理計画について'
  from public.council_members cm where cm.name = '山下茂';

  select '455af9e1-9338-4e71-8da7-3dc5372f8ef8', v_assembly_id, cm.id, 6, '申請が必要な支援制度、子育て支援について'
  from public.council_members cm where cm.name = '江藤美代子';

  select 'b50ad45f-00fb-4e35-b6e0-13211d8ff13d', v_assembly_id, cm.id, 7, '各種事業の進捗状況、ふるさと納税、教育事業、都市計画、区長会からの質問事項について'
  from public.council_members cm where cm.name = '藤島玄稔';

  -- question_topics: 会議録の質疑応答の内容に基づく

  -- 区長会からの質問事項(5番目の論点)はdisplay_order不整合防止のため上のvaluesリストに含めていないので、別途insertする

end $$;
